    let text = "The quick brown fox jumps over the lazy dog";
    let hash = sha1(text.as_bytes(), text.len(), 20, [0u8; 20]);
    let expected = b"2fd4e1c67a2d28fced849ee1bb76e7391b93eb12";
    assert_eq!(hash, expected);
}

