fn test_from_base32() {
    let mut buf = [0u8; 10];

    // "MZxw6===": M=12, Z=25, w=22, 6=6, === padding
    // = 0x12, 0x19, 0x16, 0x06, 0x00, 0x00, 0x00
    let result = from_base32("MZxw6===", &mut buf);
    assert_eq!(result, 6);
    assert_eq!(buf[0], 0x12);
    assert_eq!(buf[1], 0x19);
    assert_eq!(buf[2], 0x16);
    assert_eq!(buf[3], 0x06);

