    let result = from_base32("MZxw6YQ=", &mut buf);
    assert_eq!(result, 6);
    assert_eq!(buf[0], 0x12);
    assert_eq!(buf[1], 0x19);
    assert_eq!(buf[2], 0x16);
    assert_eq!(buf[3], 0x06);
    assert_eq!(buf[4], 0x25);
    assert_eq!(buf[5], 0x16);

